                }
            }
            if (board[i][j] == 1) {
                nextBoard[i][j] = (liveNeighbors == 2 || liveNeighbors == 3) ? 1 : 0;
            } else {
                nextBoard[i][j] = (liveNeighbors == 3) ? 1 : 0;
            }
        }
    }
